package platform.contentapi.management;

import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import platform.contentapi.execution.*;
import tools.jackson.databind.JsonNode;
import static org.assertj.core.api.Assertions.*;
import static platform.contentapi.management.SourceFixtures.*;

/** D1 -> actual SeaweedFS D2 -> actual pinned Spark D3. Synthetic sources only. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class RssSilverIT extends RssFetchFixtures {
    Path credentials,journal;BronzeFaultProxy proxy;String bronzeRuntime="bronze-d3",silverRuntime="silver-d3";boolean malformed;
    @Override byte[] feedPayload(){return (malformed?"<rss>":"<rss version=\"2.0\"><channel><item><guid>one</guid><title>One</title></item><item><title>Missing identifier</title></item></channel></rss>").getBytes(java.nio.charset.StandardCharsets.UTF_8);}
    @BeforeEach @Override void setup(){try{
        malformed=false;proxy=new BronzeFaultProxy(Objects.requireNonNull(System.getenv("BRONZE_S3_ENDPOINT")));
        credentials=Files.createTempFile(temp,"silver-credentials-",".json").toRealPath();Files.setPosixFilePermissions(credentials,PosixFilePermissions.fromString("rw-------"));Files.write(credentials,SourceJson.canonical(SourceJson.object().put("accessKey",System.getenv("BRONZE_S3_ACCESS_KEY")).put("secretKey",System.getenv("BRONZE_S3_SECRET_KEY"))));super.setup();
    }catch(Exception ex){throw new IllegalStateException(ex);}}
    @AfterEach void closeProxy(){if(proxy!=null)proxy.close();}
    @Override void storage(String id,String product,String role){if(!role.equals("BRONZE")){super.storage(id,product,role);return;}byte[] raw=SourceJson.canonical(SourceJson.object().put("importBronzeVersion",1).put("endpoint",proxy.endpoint()).put("region",System.getenv("BRONZE_S3_REGION")).put("bucket",System.getenv("BRONZE_S3_BUCKET")).put("credentialsFile",credentials.toString()));jdbc.update("INSERT INTO ddip_management.storage_bindings(binding_id,product,role,configuration_bytes,configuration_sha256,installation_id) VALUES (?,?,?,?,?,?)",id,product,role,raw,SourceJson.sha(raw),INSTALL);}
    String digest(String id){return jdbc.queryForObject("SELECT configuration_sha256 FROM ddip_management.execution_profiles WHERE profile_id=?",String.class,id);}
    void register(String id,JsonNode c){byte[] raw=SourceJson.canonical(c);jdbc.update("INSERT INTO ddip_management.execution_profiles(profile_id,configuration_bytes,configuration_sha256) VALUES (?,?,?)",id,raw,SourceJson.sha(raw));jdbc.update("INSERT INTO ddip_management.execution_profile_storage SELECT ?,binding_id FROM ddip_management.storage_bindings WHERE product=?",id,CONTENT);}
    void prepare()throws Exception {
        ready();var fetched=fetch();owner=fetched.stage().owner();journal=directory(fetched.stage());
        register(bronzeRuntime,SourceJson.object().put("bronzeRuntimeVersion",1).put("adapter","platform.ingestion.managed.ManagedBronze").put("fetchRuntimeId",runtime).put("fetchRuntimeSha256",digest(runtime)).put("runProfileId",CONTENT_PROFILE).put("runProfileSha256",digest(CONTENT_PROFILE)).put("deploymentSha256",SourceJson.sha(SourceJson.canonical(manifest))).put("controlBindingId",guard.binding().id()).put("storageBindingId",BRONZE).put("storageBindingSha256",jdbc.queryForObject("SELECT configuration_sha256 FROM ddip_management.storage_bindings WHERE binding_id=?",String.class,BRONZE)));
        owner=RssBronzeTestSupport.store(jdbc,tx,workers,guard,owner,bronzeRuntime,(p,o)->{}).owner();
        Path processing=Path.of("../../processing").toRealPath();
        var c=SourceJson.object().put("silverRuntimeVersion",1).put("bronzeRuntimeId",bronzeRuntime).put("bronzeRuntimeSha256",digest(bronzeRuntime)).put("runProfileSha256",digest(CONTENT_PROFILE)).put("deploymentSha256",SourceJson.sha(SourceJson.canonical(manifest))).put("python",Objects.requireNonNull(System.getenv("DDIP_TEST_PYTHON"))).put("javaHome",Path.of(System.getProperty("java.home")).toRealPath().toString()).put("processingRoot",processing.toString()).put("outputBindingId",SILVER_BINDING).put("tempBindingId","content-TEMP").put("seconds",180);
        c.set("modules",RssSilverTestSupport.modules(processing));c.set("versions",SourceJson.object().put("python","3.12.15").put("pyspark","4.0.2").put("boto3","1.43.114").put("java","21"));register(silverRuntime,c);
    }
    RssSilverTestSupport.Stored execute(){return execute((p,o)->{});}
    RssSilverTestSupport.Stored execute(java.util.function.BiConsumer<String,WorkerRepository.Owner> fault){return RssSilverTestSupport.execute(jdbc,tx,workers,guard,owner,silverRuntime,fault);}
    UUID inspectSilver(){return RssSilverTestSupport.inspect(jdbc,tx,workers,guard,owner.runId(),silverRuntime);}
    Path namespace(){var r=SourceJson.parse(jdbc.queryForObject("SELECT receipt_bytes FROM ddip_management.rss_deliveries",byte[].class));String key=r.get("expected").get("metadataKey").stringValue();return roots.get(SILVER_BINDING).resolve("v1/"+SourceJson.sha(r.get("bucket").stringValue().getBytes(java.nio.charset.StandardCharsets.UTF_8))+"/"+key.substring("bronze/rss/".length()).replace("metadata.json",""));}
    Map<String,String> snapshot(Path root)throws Exception {var result=new TreeMap<String,String>();try(var paths=Files.walk(root)){for(Path p:paths.filter(Files::isRegularFile).toList())result.put(root.relativize(p).toString(),SourceJson.sha(Files.readAllBytes(p))+":"+Files.getLastModifiedTime(p)+":"+Files.getAttribute(p,"unix:ino"));}return result;}
    void occupied(){assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());assertThat(count("stage_artifacts")).isZero();assertThat(requests.get()).isEqualTo(1);assertThat(proxy.puts.get()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage IN ('PREPARE_GOLD','PUBLISH_GOLD','PUBLISH_CONTENT')",Integer.class)).isZero();}
    void fixture(String mode,String... extra)throws Exception {String cp=Path.of("../../ingestion/target/test-classes").toRealPath()+java.io.File.pathSeparator+String.join(java.io.File.pathSeparator,java.util.stream.StreamSupport.stream(manifest.get("classpath").spliterator(),false).map(n->n.get("path").stringValue()).toList());var command=new ArrayList<>(List.of(Path.of(System.getProperty("java.home"),"bin/java").toString(),"-cp",cp,"platform.ingestion.managed.BronzeFixture",mode,journal.toString()));command.addAll(List.of(extra));var p=new ProcessBuilder(command).redirectError(ProcessBuilder.Redirect.DISCARD).redirectOutput(ProcessBuilder.Redirect.DISCARD).start();assertThat(p.waitFor(40,java.util.concurrent.TimeUnit.SECONDS)).isTrue();assertThat(p.exitValue()).isZero();}
    @Test void exactNativePublicationAndFullyVerifiedReplay()throws Exception {
        prepare();var original=snapshot(journal);var checkpoints=jdbc.queryForList("SELECT stage,state,row_version,checkpoint_id,command_sha256,result_sha256 FROM ddip_management.stage_invocations ORDER BY stage");byte[] receipt=jdbc.queryForObject("SELECT receipt_bytes FROM ddip_management.rss_deliveries",byte[].class);var stored=execute();owner=stored.owner();
        var evidence=SourceJson.parse(stored.evidence());assertThat(evidence.get("verification").get("native").get("counts")).isEqualTo(SourceJson.object().put("accepted",1).put("rejected",1));
        System.out.println("D3_NATIVE_EVIDENCE "+SourceJson.object().put("accepted",1).put("rejected",1).put("artifactId",stored.artifact().toString()).put("inventorySha256",evidence.get("verification").get("inventoryIdentity").get("sha256").stringValue()).put("completionSha256",SourceJson.sha(Files.readAllBytes(namespace().resolve("complete.json")))));
        assertThat(evidence.get("selection").get("identity").get("ingestionId")).isEqualTo(SourceJson.parse(receipt).get("ingestionId"));
        var before=snapshot(namespace());assertThat(inspectSilver()).isEqualTo(stored.artifact());assertThat(inspectSilver()).isEqualTo(stored.artifact());assertThat(snapshot(namespace())).isEqualTo(before);
        assertThat(snapshot(journal)).isEqualTo(original);assertThat(jdbc.queryForObject("SELECT receipt_bytes FROM ddip_management.rss_deliveries",byte[].class)).isEqualTo(receipt);
        assertThat(jdbc.queryForList("SELECT stage,state,row_version,checkpoint_id,command_sha256,result_sha256 FROM ddip_management.stage_invocations WHERE stage<>'SILVER' ORDER BY stage")).isEqualTo(checkpoints);
        assertThat(count("artifacts")).isEqualTo(6);assertThat(count("stage_artifacts")).isEqualTo(1);assertThat(count("stage_invocations")).isEqualTo(3);assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);
        assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.runs",String.class)).isEqualTo("RUNNING");assertThat(requests.get()).isEqualTo(1);assertThat(proxy.puts.get()).isEqualTo(2);
        var unrelated=content();((tools.jackson.databind.node.ObjectNode)unrelated.get("fetchSources").get(0)).put("revision",2);submit(unrelated,"unrelated-content");assertThatThrownBy(()->workers.claim(guard,owner.worker(),UUID.randomUUID())).isInstanceOf(WorkerFailure.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.runs WHERE state='QUEUED'",Integer.class)).isEqualTo(1);
        assertThat(jdbc.queryForList("SELECT child_pid,child_started_at,child_instance_id FROM ddip_management.stage_invocations WHERE stage='SILVER'").getFirst().values()).doesNotContainNull();
    }
    @ParameterizedTest @ValueSource(strings={"INTENT","BEFORE_AUTHORIZATION","AUTHORIZED","AFTER_CHILD","VERIFIED"}) void crashNeverRelaunchesSpark(String boundary)throws Exception {
        prepare();var latest=new java.util.concurrent.atomic.AtomicReference<WorkerRepository.Owner>();assertThatThrownBy(()->execute((p,o)->{latest.set(o);if(p.equals(boundary))throw new AssertionError("crash");})).isInstanceOf(AssertionError.class);owner=latest.get();occupied();var before=snapshot(roots.get(SILVER_BINDING));workers=WorkerTestSupport.enabled(jdbc,tx,INSTALL);assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);assertThat(snapshot(roots.get(SILVER_BINDING))).isEqualTo(before);
        assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage='SILVER'",Integer.class)).isEqualTo(1);
    }
    @ParameterizedTest @ValueSource(strings={"INSERT INTO ddip_management.stage_invocations","SET command_address="}) void lostLaunchAckCannotStartSpark(String sql)throws Exception {prepare();installLostCommit(sql);loseAck.set(true);assertThatThrownBy(this::execute).hasMessage("MANAGEMENT_UNAVAILABLE");occupied();assertThat(Files.exists(namespace())).isFalse();assertThatThrownBy(this::execute).hasMessage("OWNERSHIP_LOST");}
    @Test void lostVerifiedAckIsReadOnlyWithoutDuplicateRegistration()throws Exception {prepare();installLostCommit("SET state='VERIFIED',result_address=");assertThatThrownBy(()->execute((p,o)->{if(p.equals("BEFORE_CHECKPOINT"))loseAck.set(true);})).hasMessage("MANAGEMENT_UNAVAILABLE");var before=snapshot(namespace());assertThat(inspectSilver()).isNotNull();assertThatThrownBy(this::execute).hasMessage("OWNERSHIP_LOST");assertThat(snapshot(namespace())).isEqualTo(before);assertThat(count("artifacts")).isEqualTo(6);assertThat(count("stage_artifacts")).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"stale","guard","outage","interrupt"}) void authorityLossDuringChildKeepsOwnership(String fault)throws Exception {prepare();assertThatThrownBy(()->execute((p,o)->{if(p.equals("CHILD_STARTED")){switch(fault){case "stale"->jdbc.update("UPDATE ddip_management.coordinator SET row_version=row_version+1");case "guard"->guard.close();case "outage"->outage(true);case "interrupt"->Thread.currentThread().interrupt();}}})).isInstanceOf(RuntimeException.class);Thread.interrupted();if(fault.equals("outage"))outage(false);occupied();assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);}
    @ParameterizedTest @ValueSource(strings={"missing-marker","corrupt-parquet","unexpected-file"}) void outputSubstitutionBeforeVerificationFails(String fault)throws Exception {prepare();assertThatThrownBy(()->execute((p,o)->{if(p.equals("AFTER_CHILD"))try{switch(fault){case "missing-marker"->Files.delete(namespace().resolve("complete.json"));case "corrupt-parquet"->{try(var paths=Files.walk(namespace().resolve("accepted"))){Files.write(paths.filter(pth->pth.toString().endsWith(".parquet")).findFirst().orElseThrow(),new byte[]{1,2});}}case "unexpected-file"->Files.writeString(namespace().resolve("substitution"),"unexpected");}}catch(Exception ex){throw new IllegalStateException(ex);}})).isInstanceOf(RuntimeException.class);occupied();assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);}
    @Test void incompleteNamespaceNeverResumes()throws Exception {prepare();Files.createDirectories(namespace());Files.writeString(namespace().resolve("partial"),"partial");var before=snapshot(namespace());assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);occupied();assertThat(snapshot(namespace())).isEqualTo(before);}
    @Test void malformedFeedIsProcessingFailureWithoutPublication()throws Exception {malformed=true;prepare();assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);occupied();assertThat(Files.exists(namespace())).isFalse();}
    @Test void missingReceiptCannotCreateIntent()throws Exception {prepare();jdbc.update("UPDATE ddip_management.rss_deliveries SET receipt_bytes=?,row_version=row_version+1",SourceJson.canonical(SourceJson.object()));assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);assertThat(count("stage_invocations")).isEqualTo(2);occupied();}
    @Test void changedBronzeCannotReachSpark()throws Exception {prepare();proxy.fault="auth";assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);proxy.fault="none";assertThat(count("stage_invocations")).isEqualTo(2);occupied();}
    @Test void changedModuleCannotLaunch()throws Exception {prepare();var c=(tools.jackson.databind.node.ObjectNode)SourceJson.parse(jdbc.queryForObject("SELECT configuration_bytes FROM ddip_management.execution_profiles WHERE profile_id=?",byte[].class,silverRuntime));((tools.jackson.databind.node.ObjectNode)c.get("modules")).put("silver.py","0".repeat(64));silverRuntime="wrong-silver";register(silverRuntime,c);assertThatThrownBy(this::execute).hasMessage("RUNTIME_MISMATCH");assertThat(count("stage_invocations")).isEqualTo(2);occupied();}
    @ParameterizedTest @ValueSource(strings={"bad-payload","bad-metadata","remove-payload","remove-metadata"}) void originalBronzeEvidenceMustStillExist(String mode)throws Exception {prepare();if(mode.startsWith("remove"))fixture(mode);else fixture("seed",mode);assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);assertThat(count("stage_invocations")).isEqualTo(2);occupied();assertThat(Files.exists(namespace())).isFalse();}
    @Test void processStartFailureDoesNotFreeOwnership()throws Exception {prepare();Path invalid=Files.createTempFile(temp,"unstartable-",".bin");Files.setPosixFilePermissions(invalid,PosixFilePermissions.fromString("rwx------"));var c=(tools.jackson.databind.node.ObjectNode)SourceJson.parse(jdbc.queryForObject("SELECT configuration_bytes FROM ddip_management.execution_profiles WHERE profile_id=?",byte[].class,silverRuntime));c.put("python",invalid.toString());silverRuntime="unstartable";register(silverRuntime,c);assertThatThrownBy(()->execute((p,o)->{if(p.equals("AUTHORIZED"))try{Files.delete(invalid);}catch(Exception ex){throw new IllegalStateException(ex);}})).hasMessage("PROCESS_START_FAILED");occupied();assertThat(Files.exists(namespace())).isFalse();}
    @Test void changedBronzeAfterQualificationCannotCommit()throws Exception {prepare();assertThatThrownBy(()->execute((p,o)->{if(p.equals("BEFORE_CHECKPOINT"))try{fixture("seed","bad-payload");}catch(Exception ex){throw new IllegalStateException(ex);}})).hasMessage("INPUT_CHANGED");occupied();assertThatThrownBy(this::execute).isInstanceOf(RuntimeException.class);}
    @ParameterizedTest @ValueSource(strings={"artifacts","stage_artifacts","stage_invocations","audit_events"}) void verifiedRegistrationCommitsAtomically(String table)throws Exception {prepare();assertThatThrownBy(()->execute((p,o)->{if(p.equals("BEFORE_CHECKPOINT")){jdbc.execute("CREATE FUNCTION ddip_management.d3_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING MESSAGE='PRIVATE',ERRCODE='23514'; END $$");jdbc.execute("CREATE TRIGGER d3_fault BEFORE "+(table.equals("stage_invocations")?"UPDATE":"INSERT")+" ON ddip_management."+table+" FOR EACH ROW EXECUTE FUNCTION ddip_management.d3_fault()");}})).hasMessage("STATE_CONFLICT");occupied();assertThat(count("artifacts")).isEqualTo(5);assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.stage_invocations WHERE stage='SILVER'",String.class)).isEqualTo("RUNNING");}
}
